          + "_" + std::to_string(::time(nullptr));
    mkdir_p(dir);
    ::setenv("VKERNELS_TUNING_CACHE", dir.c_str(), 1);
    ::setenv("VKERNELS_TUNING_ARCH", "sm000", 1);
    tuning::reset_for_test();
  }
  ~TempStore() {
    ::setenv("VKERNELS_TUNING_CACHE", "", 1);
    ::setenv("VKERNELS_TUNING_ARCH", "", 1);
